export const LEVELS = ['A1', 'A2', 'B1', 'B2', 'C1'];

export const STAGE_SIZE = 5;

export const CEFR_META = {
  A1: { title: 'Эхлэгч',    pill: '#FFD1E8', pillTxt: '#B5175A', soft: '#FFF0F7' },
  A2: { title: 'Анхан шат', pill: '#FFE0C5', pillTxt: '#B55000', soft: '#FFF5EE' },
  B1: { title: 'Дунд',      pill: '#FFF2B5', pillTxt: '#836500', soft: '#FFFBEA' },
  B2: { title: 'Дунд-дээд', pill: '#C4F5DC', pillTxt: '#0A6038', soft: '#EDFAF3' },
  C1: { title: 'Дээд',      pill: '#DDD4FF', pillTxt: '#5230B0', soft: '#F2EEFF' },
};

export function getStages(gameType, cefr) {
  const size = gameType === 'match' ? 6 : STAGE_SIZE;
  const pool =
    gameType === 'gender'
      ? VOCAB.filter(w => w.level === cefr && w.type === 'noun')
      : VOCAB.filter(w => w.level === cefr);
  const stages = [];
  for (let i = 0; i < pool.length; i += size) {
    stages.push({
      id:       `${gameType}-${cefr}-${Math.floor(i / size)}`,
      stageNum: Math.floor(i / size) + 1,
      words:    pool.slice(i, Math.min(i + size, pool.length)),
    });
  }
  return stages;
}
